/**
 * Owner, 2026-10-15: "consultant can also review all the documents and forms
 * added by user or generated by app". One surface: open each upload (signed,
 * logged), see what OCR read and how it verified, decide; read, edit and decide
 * each generated letter; edit every field of the application form.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, fireEvent, waitFor, within } from '@testing-library/react'

const getReviewItems = vi.fn()
const getDocumentUrl = vi.fn()
const decideReviewItem = vi.fn()
const editGeneratedItem = vi.fn()
const editPreflightField = vi.fn()

vi.mock('@/lib/supabase/client', () => ({
  getSession: () => Promise.resolve({ data: { session: { access_token: 't' } } }),
}))
vi.mock('@/components/providers/toast-provider', () => ({ useToast: () => ({ toast: () => {} }) }))
vi.mock('next/navigation', () => ({ useRouter: () => ({ refresh: () => {} }) }))
vi.mock('@/lib/api/review-items-client', () => ({
  getReviewItems: (...a: unknown[]) => getReviewItems(...a),
  getDocumentUrl: (...a: unknown[]) => getDocumentUrl(...a),
  decideReviewItem: (...a: unknown[]) => decideReviewItem(...a),
  editGeneratedItem: (...a: unknown[]) => editGeneratedItem(...a),
}))
vi.mock('@/lib/api/preflight-client', () => ({
  editPreflightField: (...a: unknown[]) => editPreflightField(...a),
}))

import ReviewItemsPanel from './review-items-panel'

const ITEMS = {
  applicationId: 'app-1',
  documents: [
    {
      id: 'd1', type: 'passport', name: 'passport.pdf', uploadStatus: 'complete', ocrStatus: 'complete', createdAt: '2026-10-01',
      verifications: [{ verificationType: 'expiry_check', result: 'pass', details: {}, verifiedAt: null }],
      extractedFields: [{ fieldKey: 'passport_number', value: 'AK1182091', origin: 'ocr', confidence: 0.92 }],
      decision: null,
    },
  ],
  generated: [
    { id: 'g1', docType: 'loe', contentMd: '**To: Visa Officer**', approvedByUser: true, generatedAt: null, decision: { decision: 'changes_requested', note: 'tone', reviewerId: 'c', reviewerRole: 'consultant', createdAt: '2026-10-10' } },
  ],
  form: {
    id: 'g2', approvedByUser: false, decision: null,
    fields: [
      { key: 'duration_of_stay_days', label: 'Duration of stay (days)', value: '62', group: 'Travel', source: 'inferred' },
      { key: 'occupation', label: 'Occupation', value: 'Retired', group: 'Employment', source: 'profile' },
    ],
  },
}

describe('ReviewItemsPanel', () => {
  beforeEach(() => {
    for (const f of [getReviewItems, getDocumentUrl, decideReviewItem, editGeneratedItem, editPreflightField]) f.mockReset()
    getReviewItems.mockResolvedValue(ITEMS)
  })

  // Review finding: window.open() AFTER an await is not a user gesture any
  // more, so browsers popup-blocked it. The tab opens synchronously on click
  // and is pointed at the signed URL once it arrives.
  it('opens the tab synchronously on click, then points it at the signed URL', async () => {
    let resolveUrl: (v: { url: string; expiresIn: number }) => void = () => {}
    getDocumentUrl.mockReturnValue(new Promise((r) => { resolveUrl = r }))
    const tab = { location: { href: '' }, opener: {} as unknown, close: vi.fn() }
    const open = vi.spyOn(window, 'open').mockReturnValue(tab as unknown as Window)
    render(<ReviewItemsPanel applicationId="app-1" />)
    fireEvent.click(await screen.findByRole('button', { name: 'Open passport.pdf' }))
    expect(open).toHaveBeenCalledWith('', '_blank') // before the URL exists
    expect(tab.opener).toBeNull()
    resolveUrl({ url: 'https://db.visaai.co/signed', expiresIn: 300 })
    await waitFor(() => expect(tab.location.href).toBe('https://db.visaai.co/signed'))
    expect(getDocumentUrl).toHaveBeenCalledWith('t', 'app-1', 'd1')
    open.mockRestore()
  })

  it('closes the blank tab when the signed URL cannot be issued', async () => {
    getDocumentUrl.mockRejectedValue(new Error('access log insert failed'))
    const tab = { location: { href: '' }, opener: {} as unknown, close: vi.fn() }
    const open = vi.spyOn(window, 'open').mockReturnValue(tab as unknown as Window)
    render(<ReviewItemsPanel applicationId="app-1" />)
    fireEvent.click(await screen.findByRole('button', { name: 'Open passport.pdf' }))
    await waitFor(() => expect(tab.close).toHaveBeenCalled())
    expect(await screen.findByText(/access log insert failed/)).toBeInTheDocument()
    open.mockRestore()
  })

  it('shows what OCR read and the verification results', async () => {
    render(<ReviewItemsPanel applicationId="app-1" />)
    fireEvent.click(await screen.findByRole('button', { name: 'Details for passport.pdf' }))
    expect(screen.getByText('AK1182091')).toBeInTheDocument()
    expect(screen.getByText(/expiry_check/)).toBeInTheDocument()
  })

  it('records needs re-upload with a required note', async () => {
    decideReviewItem.mockResolvedValue({ decision: { decision: 'needs_reupload', note: 'cut off', reviewerId: 'c', reviewerRole: 'consultant', createdAt: 'x' }, notified: true })
    render(<ReviewItemsPanel applicationId="app-1" />)
    const row = (await screen.findByText('passport.pdf')).closest('li') as HTMLElement
    fireEvent.click(within(row).getByRole('button', { name: 'Needs re-upload' }))
    const confirm = within(row).getByRole('button', { name: 'Send decision' })
    expect(confirm).toBeDisabled()
    fireEvent.change(within(row).getByRole('textbox', { name: 'Note for the applicant' }), { target: { value: 'cut off' } })
    fireEvent.click(confirm)
    await waitFor(() => expect(decideReviewItem).toHaveBeenCalledWith('t', 'app-1', { itemKind: 'document', itemId: 'd1', decision: 'needs_reupload', note: 'cut off' }))
    expect(await within(row).findByText("Needs re-upload — cut off")).toBeInTheDocument()
  })

  it('renders letters as formatted text, not raw markdown, with the current decision', async () => {
    const { container } = render(<ReviewItemsPanel applicationId="app-1" />)
    expect(await screen.findByText('Letter of explanation')).toBeInTheDocument()
    expect(container.querySelector('strong')?.textContent).toBe('To: Visa Officer')
    expect(screen.queryByText(/\*\*To/)).not.toBeInTheDocument()
    expect(screen.getByText("Changes requested — tone")).toBeInTheDocument()
  })

  it('edits a letter and shows the saved version', async () => {
    editGeneratedItem.mockResolvedValue({ ...ITEMS.generated[0], contentMd: '**To: The Visa Officer**', approvedByUser: false })
    render(<ReviewItemsPanel applicationId="app-1" />)
    fireEvent.click(await screen.findByRole('button', { name: 'Edit Letter of explanation' }))
    fireEvent.change(screen.getByRole('textbox', { name: 'Letter of explanation text' }), { target: { value: '**To: The Visa Officer**' } })
    fireEvent.click(screen.getByRole('button', { name: 'Save letter' }))
    await waitFor(() => expect(editGeneratedItem).toHaveBeenCalledWith('t', 'app-1', 'g1', '**To: The Visa Officer**', undefined))
    expect(await screen.findByText('To: The Visa Officer')).toBeInTheDocument()
  })

  it('every form field is editable and saves through the auto-fill-aware field endpoint', async () => {
    editPreflightField.mockResolvedValue({ mappings: [], review: null, formUpdated: true, provenanceUpdated: false })
    render(<ReviewItemsPanel applicationId="app-1" />)
    fireEvent.click(await screen.findByRole('button', { name: 'Edit occupation' }))
    fireEvent.change(screen.getByRole('textbox', { name: 'New value for occupation' }), { target: { value: 'Retired teacher' } })
    fireEvent.click(screen.getByRole('button', { name: 'Save occupation' }))
    await waitFor(() => expect(editPreflightField).toHaveBeenCalledWith('t', 'app-1', 'occupation', 'Retired teacher', undefined))
    expect(await screen.findByText('Retired teacher')).toBeInTheDocument()
  })

  it('shows the server refusal when a locked auto-fill field is edited', async () => {
    editPreflightField.mockRejectedValue(new Error('The pre-submission review is locked'))
    render(<ReviewItemsPanel applicationId="app-1" />)
    fireEvent.click(await screen.findByRole('button', { name: 'Edit duration_of_stay_days' }))
    fireEvent.click(screen.getByRole('button', { name: 'Save duration_of_stay_days' }))
    expect(await screen.findByText(/review is locked/)).toBeInTheDocument()
  })

  it('shows a refusal (e.g. not the assigned consultant) instead of an empty review', async () => {
    getReviewItems.mockRejectedValue(new Error('consultant c2 is not the active assignee'))
    render(<ReviewItemsPanel applicationId="app-1" />)
    expect(await screen.findByText(/not the active assignee/)).toBeInTheDocument()
  })
})
